public class OrderDto
{
    public int Id { get; set; }
    public string ProductName { get; set; }
    public decimal Amount { get; set; }
}

[HttpPost("/api/orders")]
public IActionResult Create([FromBody] OrderDto order, [FromQuery] bool notify)
{
    // order is read from the JSON request body
    // notify is read from the query string, e.g. /api/orders?notify=true

    if (notify)
    {
        _notifier.Send("New order received");
    }

    return CreatedAtAction(nameof(GetById), new { id = order.Id }, order);
}

public class UpdateProductRequest
{
    public string Name { get; set; }
    public decimal Price { get; set; }
}

[HttpPut("/api/products/{id}")]
public IActionResult Update([FromRoute] int id, [FromBody] UpdateProductRequest request)
{
    var product = _repo.GetById(id);
    if (product == null) return NotFound();

    product.Name = request.Name;
    product.Price = request.Price;
    _repo.Save(product);

    return NoContent();
}

public class SearchQuery
{
    [FromRoute]
    public int CategoryId { get; set; }

    [FromQuery]
    public string Keyword { get; set; }

    [FromQuery]
    public int Page { get; set; } = 1;
}

// Route: /categories/5/search?keyword=shoes&page=2
[HttpGet("/categories/{categoryId}/search")]
public IActionResult Search(SearchQuery query)
{
    // query.CategoryId = 5 from route
    // query.Keyword = "shoes" from query string
    // query.Page = 2 from query string
    return Ok(_repo.Search(query));
}
